import csv, math, statistics, json, html
from datetime import datetime
from collections import defaultdict

DATA='/app/benchmark/data.csv'
OUT='/app/output/final_report.html'
rows=[]
with open(DATA, newline='') as f:
    for r in csv.DictReader(f):
        dt=datetime.fromisoformat(r['Date']).replace(tzinfo=None)
        rows.append({
            'date':dt,'open':float(r['Open']),'high':float(r['High']),'low':float(r['Low']),'close':float(r['Close']),
            'volume':int(r['Volume']),'dividends':float(r['Dividends']),'splits':float(r['Stock Splits'])
        })

start,end=rows[0],rows[-1]
years=(end['date']-start['date']).days/365.25
cum_return=end['close']/start['close']-1
cagr=(end['close']/start['close'])**(1/years)-1
rets=[rows[i]['close']/rows[i-1]['close']-1 for i in range(1,len(rows))]
ann_vol=statistics.stdev(rets)*math.sqrt(252)
daily_avg=statistics.mean(rets)
median_daily=statistics.median(rets)
# drawdown series
peak=rows[0]; maxdd=0; maxinfo=(rows[0],rows[0])
dd_series=[]
for r in rows:
    if r['close']>peak['close']: peak=r
    dd=r['close']/peak['close']-1
    dd_series.append({'date':r['date'], 'drawdown':dd})
    if dd<maxdd:
        maxdd=dd; maxinfo=(peak,r)
max_recovery=None
for r in rows[rows.index(maxinfo[1]):]:
    if r['close']>=maxinfo[0]['close']:
        max_recovery=r; break
ath=max(rows, key=lambda r:r['close'])
atl=min(rows, key=lambda r:r['close'])

# drawdown episodes
episodes=[]; peak=rows[0]; indd=False; trough=None
for r in rows[1:]:
    if not indd:
        if r['close']>=peak['close']:
            peak=r
        else:
            indd=True; trough=r
    else:
        if r['close']<trough['close']: trough=r
        if r['close']>=peak['close']:
            episodes.append({'peak':peak,'trough':trough,'recovery':r,'dd':trough['close']/peak['close']-1,
                             'days_to_trough':(trough['date']-peak['date']).days,'days_to_recovery':(r['date']-peak['date']).days})
            peak=r; indd=False; trough=None
if indd:
    episodes.append({'peak':peak,'trough':trough,'recovery':None,'dd':trough['close']/peak['close']-1,
                     'days_to_trough':(trough['date']-peak['date']).days,'days_to_recovery':None})
major_drawdowns=sorted([e for e in episodes if e['dd']<=-0.2], key=lambda e:e['dd'])[:10]

# decades and yearly data
def period_metrics(label, sub):
    rr=[sub[i]['close']/sub[i-1]['close']-1 for i in range(1,len(sub))]
    yrs=(sub[-1]['date']-sub[0]['date']).days/365.25
    ret=sub[-1]['close']/sub[0]['close']-1
    cg=(sub[-1]['close']/sub[0]['close'])**(1/yrs)-1 if yrs>0 else None
    vol=statistics.stdev(rr)*math.sqrt(252) if len(rr)>1 else 0
    pk=sub[0]; dd=0
    for r in sub:
        if r['close']>pk['close']: pk=r
        dd=min(dd, r['close']/pk['close']-1)
    div=sum(r['dividends'] for r in sub)
    avgvol=sum(r['volume'] for r in sub)/len(sub)
    return {'label':label,'start':sub[0]['date'],'end':sub[-1]['date'],'rows':len(sub),'return':ret,'cagr':cg,'vol':vol,'mdd':dd,'dividends':div,'avgvol':avgvol,'start_close':sub[0]['close'],'end_close':sub[-1]['close']}

decades=[]
for dec in [1970,1980,1990,2000,2010,2020]:
    sub=[r for r in rows if dec<=r['date'].year<=dec+9]
    decades.append(period_metrics(f"{dec}s" if dec<2020 else "2020s to Mar-2026", sub))

subperiod_defs=[('1972–1979',1972,1979),('1980–1989',1980,1989),('1990–1999',1990,1999),('2000–2009',2000,2009),('2010–2019',2010,2019),('2020–Mar 2026',2020,2026),('Post-GFC: 2009–Mar 2026',2009,2026)]
subperiods=[period_metrics(name, [r for r in rows if a<=r['date'].year<=b]) for name,a,b in subperiod_defs]

year_groups=defaultdict(list)
for r in rows: year_groups[r['date'].year].append(r)
yearly=[]
for y in sorted(year_groups):
    sub=year_groups[y]
    rr=[sub[i]['close']/sub[i-1]['close']-1 for i in range(1,len(sub))]
    pk=sub[0]; dd=0
    for r in sub:
        if r['close']>pk['close']: pk=r
        dd=min(dd, r['close']/pk['close']-1)
    yearly.append({'year':y,'close':sub[-1]['close'],'return':sub[-1]['close']/sub[0]['close']-1,'div':sum(r['dividends'] for r in sub),'avgvol':sum(r['volume'] for r in sub)/len(sub),'vol':statistics.stdev(rr)*math.sqrt(252) if len(rr)>1 else 0,'mdd':dd})

# corporate actions
dividend_rows=[r for r in rows if r['dividends']>0]
splits=[r for r in rows if r['splits']>0]
# dividend yield based on sum dividends in year / final close of that calendar year
for y in yearly:
    y['yield'] = y['div']/y['close'] if y['close'] else 0

# event windows
event_defs=[('1973–74 bear market','1973-01-01','1974-12-31'),('1987 crash year','1987-01-01','1987-12-31'),('Dot-com / 9-11 period','2000-01-01','2002-12-31'),('Global Financial Crisis','2007-01-01','2009-12-31'),('COVID shock','2020-01-01','2020-12-31'),('2022 drawdown','2022-01-01','2022-12-31')]
events=[]
for name,s,e in event_defs:
    sdt=datetime.fromisoformat(s); edt=datetime.fromisoformat(e)
    sub=[r for r in rows if sdt<=r['date']<=edt]
    pk=sub[0]; mdd=0; info=(pk,pk)
    for r in sub:
        if r['close']>pk['close']: pk=r
        dd=r['close']/pk['close']-1
        if dd<mdd: mdd=dd; info=(pk,r)
    events.append({'name':name,'start':sub[0],'end':sub[-1],'return':sub[-1]['close']/sub[0]['close']-1,'mdd':mdd,'peak':info[0],'trough':info[1]})

daily_moves=[(rows[i]['close']/rows[i-1]['close']-1, rows[i]) for i in range(1,len(rows))]
best_moves=sorted(daily_moves,key=lambda x:x[0],reverse=True)[:5]
worst_moves=sorted(daily_moves,key=lambda x:x[0])[:5]

# Formatting helpers
def pct(x, d=1): return f"{x*100:,.{d}f}%"
def money(x, d=2): return f"${x:,.{d}f}"
def num(x, d=0): return f"{x:,.{d}f}"
def dt(d): return d.strftime('%b %-d, %Y') if hasattr(d,'strftime') else str(d)
def yr(d): return d.strftime('%Y-%m-%d')

def table(headers, data_rows, cls=''):
    h=''.join(f'<th>{html.escape(str(x))}</th>' for x in headers)
    body=''.join('<tr>'+''.join(f'<td>{cell}</td>' for cell in row)+'</tr>' for row in data_rows)
    return f'<table class="{cls}"><thead><tr>{h}</tr></thead><tbody>{body}</tbody></table>'

# SVG chart helpers
COLORS={'blue':'#1f5eff','navy':'#16213e','green':'#0f9f6e','red':'#c0392b','orange':'#e67e22','gray':'#667085','grid':'#e6eaf0','light':'#f8fafc','purple':'#6941c6'}

def scale(vals, lo=None, hi=None, pad=0.05):
    if lo is None: lo=min(vals)
    if hi is None: hi=max(vals)
    if hi==lo:
        hi=lo+1
    span=hi-lo
    return lo-span*pad, hi+span*pad

def path_chart(points, w=980, h=360, ylog=False, color='#1f5eff', area=False, yfmt=None, title=None, events=None):
    ml,mr,mt,mb=64,22,24,42
    xs=[p[0].timestamp() for p in points]
    ys=[p[1] for p in points if p[1] is not None]
    if ylog:
        yvals=[math.log(max(p[1],1e-9)) for p in points]
        ylo,yhi=scale(yvals, pad=0.02)
        def ymap(v): return mt+(yhi-math.log(max(v,1e-9)))/(yhi-ylo)*(h-mt-mb)
        yticks=[]
        # logarithmic-ish ticks from powers/rounds within range
        candidates=[0.5,1,2,5,10,20,50,100,200,300,500]
        for c in candidates:
            if min(ys)<=c<=max(ys): yticks.append(c)
    else:
        ylo,yhi=scale(ys, pad=0.08)
        def ymap(v): return mt+(yhi-v)/(yhi-ylo)*(h-mt-mb)
        yticks=[ylo+(yhi-ylo)*i/4 for i in range(5)]
    xlo,xhi=min(xs),max(xs)
    def xmap(d): return ml+(d.timestamp()-xlo)/(xhi-xlo)*(w-ml-mr)
    coords=[(xmap(d),ymap(v)) for d,v in points]
    d='M '+' L '.join(f'{x:.2f},{y:.2f}' for x,y in coords)
    svg=[f'<svg viewBox="0 0 {w} {h}" role="img" aria-label="{html.escape(title or "chart")}">']
    svg.append(f'<rect width="{w}" height="{h}" fill="white" rx="14"/>')
    for t in yticks:
        y=ymap(t)
        svg.append(f'<line x1="{ml}" x2="{w-mr}" y1="{y:.1f}" y2="{y:.1f}" stroke="{COLORS["grid"]}"/>')
        lab=yfmt(t) if yfmt else f'{t:.0f}'
        svg.append(f'<text x="{ml-10}" y="{y+4:.1f}" text-anchor="end" font-size="11" fill="{COLORS["gray"]}">{html.escape(lab)}</text>')
    for year in [1980,1990,2000,2010,2020]:
        xd=xmap(datetime(year,1,1))
        svg.append(f'<line x1="{xd:.1f}" x2="{xd:.1f}" y1="{mt}" y2="{h-mb}" stroke="#f1f3f7"/>')
        svg.append(f'<text x="{xd:.1f}" y="{h-17}" text-anchor="middle" font-size="11" fill="{COLORS["gray"]}">{year}</text>')
    if events:
        for ev in events:
            xd=xmap(ev['date'])
            svg.append(f'<line x1="{xd:.1f}" x2="{xd:.1f}" y1="{mt}" y2="{h-mb}" stroke="{ev.get("color", COLORS["orange"])}" stroke-width="1.3" stroke-dasharray="4 4"/>')
            svg.append(f'<text x="{xd+4:.1f}" y="{mt+13}" font-size="10" fill="{ev.get("color", COLORS["orange"])}">{html.escape(ev["label"])}</text>')
    if area:
        baseline=h-mb
        area_d=d+f' L {coords[-1][0]:.2f},{baseline} L {coords[0][0]:.2f},{baseline} Z'
        svg.append(f'<path d="{area_d}" fill="{color}" opacity="0.10"/>')
    svg.append(f'<path d="{d}" fill="none" stroke="{color}" stroke-width="2.4"/>')
    svg.append(f'<line x1="{ml}" x2="{w-mr}" y1="{h-mb}" y2="{h-mb}" stroke="#ccd3df"/>')
    svg.append(f'<line x1="{ml}" x2="{ml}" y1="{mt}" y2="{h-mb}" stroke="#ccd3df"/>')
    svg.append('</svg>')
    return ''.join(svg)

def bar_chart(items, value_key, label_key='label', w=760, h=320, color='#1f5eff', fmt=lambda x:str(x), title='bar chart', zero=True):
    ml,mr,mt,mb=58,20,22,58
    vals=[it[value_key] for it in items]
    lo=min(0,min(vals)) if zero else min(vals); hi=max(0,max(vals)) if zero else max(vals)
    if hi==lo: hi=lo+1
    span=hi-lo
    lo-=span*0.08; hi+=span*0.08
    def y(v): return mt+(hi-v)/(hi-lo)*(h-mt-mb)
    n=len(items); bw=(w-ml-mr)/n*0.62; gap=(w-ml-mr)/n
    svg=[f'<svg viewBox="0 0 {w} {h}" role="img" aria-label="{html.escape(title)}"><rect width="{w}" height="{h}" fill="white" rx="14"/>']
    for i in range(5):
        v=lo+(hi-lo)*i/4; yy=y(v)
        svg.append(f'<line x1="{ml}" x2="{w-mr}" y1="{yy:.1f}" y2="{yy:.1f}" stroke="{COLORS["grid"]}"/>')
        svg.append(f'<text x="{ml-9}" y="{yy+4:.1f}" text-anchor="end" font-size="11" fill="{COLORS["gray"]}">{html.escape(fmt(v))}</text>')
    y0=y(0)
    svg.append(f'<line x1="{ml}" x2="{w-mr}" y1="{y0:.1f}" y2="{y0:.1f}" stroke="#aeb7c5"/>')
    for i,it in enumerate(items):
        x=ml+i*gap+(gap-bw)/2; yy=y(it[value_key]); height=abs(y0-yy)
        fill=it.get('color') or (COLORS['green'] if it[value_key]>=0 else COLORS['red'])
        svg.append(f'<rect x="{x:.1f}" y="{min(yy,y0):.1f}" width="{bw:.1f}" height="{height:.1f}" fill="{fill}" rx="4"/>')
        svg.append(f'<text x="{x+bw/2:.1f}" y="{h-32}" text-anchor="middle" font-size="11" fill="{COLORS["gray"]}">{html.escape(str(it[label_key]))}</text>')
        svg.append(f'<text x="{x+bw/2:.1f}" y="{(min(yy,y0)-6 if it[value_key]>=0 else max(yy,y0)+14):.1f}" text-anchor="middle" font-size="10" fill="{COLORS["navy"]}">{html.escape(fmt(it[value_key]))}</text>')
    svg.append('</svg>')
    return ''.join(svg)

def small_multiple_decades(metrics):
    cards=[]
    for m in metrics:
        vals=[{'label':'Return','value_key':m['return'],'v':m['return']},{'label':'Vol.','v':m['vol']},{'label':'MDD','v':m['mdd']}]
    return ''

def mini_spark(points, w=220, h=70, color='#1f5eff'):
    xs=[p[0].timestamp() for p in points]; ys=[p[1] for p in points]
    xlo,xhi=min(xs),max(xs); ylo,yhi=scale(ys, pad=0.12)
    def x(d): return 6+(d.timestamp()-xlo)/(xhi-xlo)*(w-12)
    def y(v): return 6+(yhi-v)/(yhi-ylo)*(h-12)
    d='M '+' L '.join(f'{x(a):.1f},{y(b):.1f}' for a,b in points)
    return f'<svg viewBox="0 0 {w} {h}"><path d="{d}" fill="none" stroke="{color}" stroke-width="2"/><line x1="6" x2="{w-6}" y1="{h-6}" y2="{h-6}" stroke="#eef1f6"/></svg>'

# Data downsampling for SVG
price_points=[(r['date'],r['close']) for i,r in enumerate(rows) if i%8==0 or i==len(rows)-1]
dd_points=[(r['date'],r['drawdown']) for i,r in enumerate(dd_series) if i%8==0 or i==len(dd_series)-1]
volume_year_points=[(datetime(y['year'],12,31), y['avgvol']) for y in yearly]
div_year_points=[(datetime(y['year'],12,31), y['div']) for y in yearly]
yield_year_points=[(datetime(y['year'],12,31), y['yield']) for y in yearly if y['div']>0]
trend_events=[{'date':datetime(1987,10,19),'label':'1987', 'color':COLORS['orange']},{'date':datetime(2001,9,17),'label':'9/11', 'color':COLORS['orange']},{'date':datetime(2009,3,6),'label':'GFC trough', 'color':COLORS['red']},{'date':datetime(2020,3,23),'label':'COVID trough', 'color':COLORS['red']}]

price_svg=path_chart(price_points, ylog=True, color=COLORS['blue'], area=True, yfmt=lambda v:f'${v:g}', title='AXP closing price, log scale', events=trend_events)
dd_svg=path_chart(dd_points, ylog=False, color=COLORS['red'], area=True, yfmt=lambda v:pct(v,0), title='AXP drawdown from prior high')
dec_return_svg=bar_chart(decades,'return',w=760,h=310,fmt=lambda v:pct(v,0),title='Decade total return')
dec_vol_svg=bar_chart([{**m,'color':COLORS['purple']} for m in decades],'vol',w=760,h=310,fmt=lambda v:pct(v,0),title='Decade annualized volatility')
vol_svg=path_chart(volume_year_points,w=760,h=300,color=COLORS['purple'],area=True,yfmt=lambda v:f'{v/1_000_000:.1f}M',title='Average daily volume by year')
div_svg=bar_chart([{'label':str(y['year'])[-2:],'div':y['div'], 'color':COLORS['green']} for y in yearly if y['year']>=1990], 'div', w=880, h=300, fmt=lambda v:f'${v:.1f}', title='Annual dividends per share since 1990')
yield_svg=path_chart(yield_year_points,w=760,h=300,color=COLORS['green'],area=True,yfmt=lambda v:pct(v,1),title='Annual dividend yield proxy')

# Tables
decade_table=table(['Period','Dates','Start Close','End Close','Total Return','CAGR','Ann. Volatility','Max Drawdown','Dividends','Avg Daily Volume'],[
    [m['label'], f"{yr(m['start'])} – {yr(m['end'])}", money(m['start_close']), money(m['end_close']), pct(m['return'],1), pct(m['cagr'],1), pct(m['vol'],1), pct(m['mdd'],1), money(m['dividends']), num(m['avgvol'])] for m in decades
])
