])
drawdown_table=table(['Rank','Peak Date','Trough Date','Recovery Date','Peak Close','Trough Close','Drawdown','Days to Trough','Days to Recovery'],[
    [i+1, yr(e['peak']['date']), yr(e['trough']['date']), yr(e['recovery']['date']) if e['recovery'] else 'Not recovered in dataset', money(e['peak']['close']), money(e['trough']['close']), pct(e['dd'],1), num(e['days_to_trough']), num(e['days_to_recovery']) if e['days_to_recovery'] is not None else 'N/A'] for i,e in enumerate(major_drawdowns)
])
event_table=table(['Episode','Window','Window Return','Worst Drawdown','Drawdown Peak','Drawdown Trough'],[
    [e['name'], f"{yr(e['start']['date'])} – {yr(e['end']['date'])}", pct(e['return'],1), pct(e['mdd'],1), f"{yr(e['peak']['date'])} ({money(e['peak']['close'])})", f"{yr(e['trough']['date'])} ({money(e['trough']['close'])})"] for e in events
