])
splits_table=table(['Date','Recorded Split Ratio'], [[yr(r['date']), f"{r['splits']:.6g}"] for r in splits])
recent_div_table=table(['Year','Dividends Per Share','Year-End Close','Dividend Yield Proxy'], [[y['year'], money(y['div']), money(y['close']), pct(y['yield'],2)] for y in yearly[-12:]])

# mini cards for decades
mini_cards=[]
for m in decades:
    pts=[(r['date'], r['close']) for r in rows if m['start']<=r['date']<=m['end']]
    step=max(1,len(pts)//55); pts=pts[::step]+([pts[-1]] if pts[-1] not in pts[::step] else [])
